<script setup>
import {useDramaI18n} from './useDramaI18n.js';const {language,tr}=useDramaI18n();
import DramaCastSearch from './DramaCastSearch.vue';
import {trapModalTab} from '../utils/modalFocus.js';
import {lockModalScroll} from '../utils/modalScrollLock.js';
import BaseModal from '../components/BaseModal.vue';
import {call} from '../api/supabase';
import {createDramaIntake} from './intake.js';
import {onMounted,onBeforeUnmount} from 'vue';
import DramaWeekdaysEditor from './DramaWeekdaysEditor.vue';
import DramaImageEditor from './DramaImageEditor.vue';
import {dramaImages,validateDramaImages} from './images.js';
import {productionCompanyOptions} from './companies.js';
const props=defineProps({scheduleArtists:{type:Array,default:()=>[]},platforms:{type:Array,default:()=>[]}});

import {ref,computed} from 'vue';
import {dramaTypes,validateDrama,generateSchedule} from './schedule.js';
const emit=defineEmits(['close','submitted']);
const error=ref('');
let draft;try{draft=JSON.parse(localStorage.getItem('chob-public-drama-draft'));if(!draft||!Array.isArray(draft.rules)||!Array.isArray(draft.cast))draft=null;}catch{}
const editing=ref(draft||{id:crypto.randomUUID(),titleZh:'',titleEn:'',titleTh:'',types:[],production:'',poster:'',source:'',synopsis:'',cast:[],rules:[]});
function addRule(){editing.value.rules.push({id:crypto.randomUUID(),platformId:props.platforms[0]?.id||'',premiere:'',totalEpisodes:12,weekdays:[],phases:[],episodesPerRelease:1,time:'21:30',timezone:'Asia/Bangkok'});}
function addCast(){editing.value.cast.push({artistId:'',name:'',role:'',lead:false});}
const formRoot=ref(null);let previousFocus;
const savedSnapshot=ref(JSON.stringify(editing.value)),confirmClose=ref(false),busy=ref(false);
const dirty=computed(()=>JSON.stringify(editing.value)!==savedSnapshot.value);
function requestClose(){if(busy.value)return;if(dirty.value)confirmClose.value=true;else emit('close');}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
function escape(e){if(confirmClose.value)return;trapModalTab(e,formRoot.value);if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();requestClose();}}
let releaseScroll;onMounted(()=>{previousFocus=document.activeElement;formRoot.value?.focus();releaseScroll=lockModalScroll();window.addEventListener('beforeunload',beforeUnload);document.addEventListener('keydown',escape,true);});
onBeforeUnmount(()=>{releaseScroll?.();previousFocus?.focus();window.removeEventListener('beforeunload',beforeUnload);document.removeEventListener('keydown',escape,true);});
function saveDraft(close=false){try{localStorage.setItem('chob-public-drama-draft',JSON.stringify(editing.value));savedSnapshot.value=JSON.stringify(editing.value);error.value='草稿已保存到本机，尚未提交审核。';if(close)emit('close');return true;}catch{error.value='草稿保存失败，请勿关闭窗口。';return false;}}
async function save(){if(busy.value)return;busy.value=true;try{validateDrama(editing.value);validateDramaImages(editing.value);if(editing.value.cast.some(c=>!c.artistId))throw Error('请选择匹配的卡司艺人，或移除空白卡司行');for(const rule of editing.value.rules)generateSchedule(editing.value,rule);await createDramaIntake(call)({id:editing.value.id,kind:'addition',payload:JSON.parse(JSON.stringify(editing.value))});localStorage.removeItem('chob-public-drama-draft');savedSnapshot.value=JSON.stringify(editing.value);error.value='已提交剧集审核，审核通过后也不会自动公开。';confirmClose.value=false;emit('submitted');emit('close');}catch(e){error.value=e.message;}finally{busy.value=false;}}
const artistChoices=computed(()=>props.scheduleArtists.map(a=>({...a,name:a.en_name||a.name||a.name_en||a.name_zh||a.nickname||'未命名艺人'})));
const platformChoices=computed(()=>props.platforms);
const companyChoices=computed(()=>productionCompanyOptions(props.scheduleArtists.length?props.scheduleArtists:[],editing.value?.productionCompany||''));
function setImages(images){editing.value.images=images;editing.value.poster=images.find(url=>url.trim())||'';}
</script>
<template><Teleport to="body"><div v-if="editing" class="overlay drama-submission-overlay" @click.self="requestClose"><form ref="formRoot" role="dialog" aria-modal="true" :aria-label="tr('新增剧集')" tabindex="-1" class="dialog editor" @submit.prevent="save"><button type="button" class="close" @click="requestClose">{{tr('取消 ×')}}</button><h2>{{tr('新增剧集')}}</h2><p class="muted">{{tr('剧集投稿独立审核；存草稿仅保存在本机，提交后不会直接公开。')}}</p><p class="muted">{{tr('三种剧名至少填写一项；没有明确首播日期时只进入剧集库。')}}</p><label v-for="(label,k) in {titleZh:'中文名',titleEn:'英文名',titleTh:'泰语名',source:'官方来源链接'}">{{tr(label)}}<input v-model="editing[k]"></label><DramaImageEditor :model-value="editing.images||(dramaImages(editing).length?dramaImages(editing):[''])" @update:model-value="setImages" /><label>{{tr('出品公司')}}<select v-model="editing.productionCompany"><option :value="undefined">{{tr('请选择出品公司')}}</option><option value="">{{tr('待公布')}}</option><option v-for="company in companyChoices" :key="company" :value="company">{{company}}</option></select><small v-if="!companyChoices.length">{{tr('暂无公司资料，载入 Schedule 艺人资料库后可选择。')}}</small></label><label>{{tr('简介')}}<textarea v-model="editing.synopsis"></textarea></label><fieldset><legend>{{tr('类型')}}</legend><div class="type-grid"><label v-for="t in dramaTypes" class="inline"><input type="checkbox" v-model="editing.types" :value="t">{{tr(t)}}</label></div></fieldset><label>{{tr('制作进度')}}<select v-model="editing.production"><option value="">{{tr('未填写（不展示）')}}</option><option value="已公布">{{tr('已公布')}}</option><option value="未开机">{{tr('未开机')}}</option><option value="已开机">{{tr('已开机')}}</option><option value="已杀青">{{tr('已杀青')}}</option></select></label><h3>{{tr('卡司')}}</h3><div class="panel" v-for="(c,i) in editing.cast"><DramaCastSearch :model-value="c.artistId" :fallback-name="c.name" :artists="artistChoices" @select="artist=>{c.artistId=artist?.id||'';c.name=artist?.en_name||artist?.name||''}"/><input v-model="c.role" :placeholder="tr('角色名称')"><label class="inline"><input type="checkbox" v-model="c.lead">{{tr('主演')}}</label><button type="button" @click="editing.cast.splice(i,1)">{{tr('移除')}}</button></div><button type="button" @click="addCast">{{tr('＋ 卡司')}}</button><h3>{{tr('播出安排')}}</h3><div class="panel" v-for="(r,i) in editing.rules"><label>{{tr('平台')}}<select v-model="r.platformId"><option v-for="p in platformChoices" :value="p.id">{{p.name}}</option></select></label><label>{{tr('首播日期')}}<input type="date" v-model="r.premiere"></label><label>{{tr('总集数')}}<label class="inline"><input type="checkbox" v-model="r.totalEpisodesUnknown" @change="r.totalEpisodes=r.totalEpisodesUnknown?null:12">{{tr('未知')}}</label><input :disabled="r.totalEpisodesUnknown" :placeholder="tr(r.totalEpisodesUnknown?'未知':'请输入总集数')" type="number" min="1" max="1000" v-model.number="r.totalEpisodes"></label><DramaWeekdaysEditor v-model="editing.rules[i]" /><label>{{tr('每次更新集数')}}<input type="number" min="1" max="1000" v-model.number="r.episodesPerRelease"></label><label>{{tr('播出时间')}}<input type="time" v-model="r.time"></label><label>{{tr('时区')}}<select v-model="r.timezone"><option>Asia/Bangkok</option><option>Asia/Shanghai</option><option>UTC</option></select></label><button type="button" @click="editing.rules.splice(i,1)">{{tr('移除此平台排期')}}</button></div><div class="rule-add-row"><button type="button" @click="addRule">{{tr('＋ 平台排期')}}</button></div><p v-if="error" role="alert" class="error">{{error}}</p><div class="form-actions"><button type="button" @click="saveDraft(false)">{{tr('存草稿')}}</button><button class="primary" :disabled="busy">{{tr(busy?'提交中…':'提交审核')}}</button></div></form></div>
</Teleport><BaseModal v-if="confirmClose" panel-class="drama-submission-confirm" :title="tr('离开前如何处理资料？')" @close="confirmClose=false"><p>{{tr('尚有未保存的修改。')}}</p><p role="alert">{{error}}</p><div class="close-actions"><button :disabled="busy" @click="saveDraft(true)">{{tr('保存草稿并关闭')}}</button><button :disabled="busy" @click="save">{{tr('提交审核')}}</button><button :disabled="busy" @click="emit('close')">{{tr('不保存并关闭')}}</button><button @click="confirmClose=false">{{tr('继续填写')}}</button></div></BaseModal></template><style scoped>
*{box-sizing:border-box}body{margin:0;background:#fff;color:#303b35;font:15px/1.6 system-ui,-apple-system,'Microsoft YaHei',sans-serif}button,input,select,textarea{font:inherit}button,a{cursor:pointer}button{border:1px solid #d9ded7;background:white;border-radius:8px;padding:8px 14px;color:inherit}button:hover{background:#EDF2F8}input,select,textarea{border:1px solid #d9ded7;border-radius:7px;padding:9px;background:white;max-width:100%}textarea{min-height:85px}header{display:flex;gap:20px;align-items:center;padding:24px 5%;border-bottom:1px solid #e4e5dd}.brand{font-size:25px;font-weight:800;letter-spacing:3px;text-decoration:none;color:#3f5848}.brand span{display:block;font-size:9px;letter-spacing:4px}.private{margin-left:auto;font-size:12px;color:#777}main{max-width:1280px;margin:auto;padding:40px 30px}.heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:11px;letter-spacing:3px;color:#86927d}h1{font-size:44px;margin:8px 0;font-family:Georgia,serif}h1 em{font:normal 21px system-ui;margin-left:12px;color:#89957d}h2{font-size:23px}h3{font-size:17px}.muted,small{color:#7d857d}.primary{background:#587DAA;color:white;border-color:#587DAA}.primary:hover{background:#466B98}nav{display:flex;gap:22px;border-bottom:1px solid #dfe3da;margin:30px 0}nav button{border:0;border-radius:0;background:none;padding:14px 4px}.active{border-bottom:3px solid #587DAA!important;font-weight:700}.toolbar{display:flex;justify-content:space-between;gap:16px;margin:20px 0}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:1px solid #e1e5dc;border-left:1px solid #e1e5dc;background:white}.weekday{text-align:center;font-weight:400;padding:12px;background:#f1f3ed}.day{min-height:150px;border-right:1px solid #e1e5dc;border-bottom:1px solid #e1e5dc;padding:8px}.blank{background:#f7f7f3}.day-number{font-size:13px;color:#8b9288}.chip{display:block;width:100%;text-align:left;padding:7px;margin:5px 0;font-size:12px;background:#edf2e9;border:0;border-left:3px solid #8ca37b;border-radius:4px}.chip small{display:block;font-size:10px}.changed{background:#f7e9e2;border-color:#c69077}.strike{text-decoration:line-through}.event{background:#f1ecf7;border-color:#a48cbf}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.card{background:white;padding:18px;border:1px solid #e1e5dc;border-radius:12px}.card-main{display:flex;gap:22px;text-align:left;width:100%;border:0;padding:0;background:none}.card-main img,.poster{width:115px;height:160px;object-fit:cover;border-radius:6px;flex-shrink:0}.poster{background:linear-gradient(145deg,#bdcbb4,#758d75);color:white;display:grid;place-content:center;text-align:center;font:20px Georgia;letter-spacing:3px}.badge{font-size:11px;background:#edf1e6;padding:4px 9px;border-radius:20px}.card h2{font-size:20px;margin:10px 0}.card p{font-size:12px;margin:5px 0}.card>button:last-child{margin-top:12px;font-size:12px}.overlay{position:fixed;inset:0;background:#16261f66;display:flex;align-items:center;justify-content:center;z-index:10;padding:24px}.dialog{position:relative;background:#fff;border-radius:14px;padding:32px;width:650px;max-height:90vh;overflow:auto;box-shadow:0 20px 80px #14271d44}.close{float:right}.hero{position:relative;clear:both}.hero img{width:100%;max-height:280px;object-fit:contain}.banner{background:#f0d9c9;padding:16px;margin:18px 0}.banner strong{display:block;font-size:18px}.banner span{font-size:15px}.announcement{background:#f3e8db;border-radius:8px;padding:15px;margin:15px 0}.announcement p{margin:7px 0}.platform{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}.platform img{height:16px;width:auto;max-width:70px;object-fit:contain}.editor label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.editor .inline{display:inline-flex;flex-direction:row;margin-right:14px;align-items:center}.editor input[type=checkbox]{width:auto}.panel{border:1px solid #D8E0E9;padding:15px;border-radius:8px;margin:15px 0}.panel input,.panel select{margin:5px}.event-row{display:flex;align-items:center;gap:14px;flex-wrap:wrap;width:100%;padding:18px;border-bottom:1px solid #D8E0E9}.event-row label{display:flex;flex-direction:column}.error{color:#a33e29}footer{padding:25px 5%;border-top:1px solid #e1e5dc;font-size:11px;letter-spacing:2px;color:#8b9288}footer span{float:right}@media(max-width:700px){main{padding:20px 12px}.private{font-size:10px}header{gap:8px;padding:15px}.heading{align-items:start}h1{font-size:30px}h1 em{display:block;margin:0;font-size:17px}.cards{grid-template-columns:1fr}.calendar{min-width:700px}section:has(>.calendar){overflow:auto}.day{min-height:120px}nav{gap:10px}nav button{font-size:13px}.dialog{padding:22px}.toolbar{font-size:11px}.overlay{padding:10px}}
.editor fieldset{border:0;padding:0;margin:24px 0;min-width:0}.editor fieldset legend{padding:0;margin-bottom:14px}.editor fieldset .inline{margin:0;display:flex;gap:9px;align-items:center}.type-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px 24px}.editor .form-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px;padding-top:20px;border-top:1px solid #e1e5dc}.rule-add-row{display:block;margin:18px 0}@media(max-width:500px){.type-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}
.overlay{z-index:1000;padding:16px;overflow-y:auto;overscroll-behavior:contain;font:15px/1.6 system-ui,-apple-system,'Microsoft YaHei',sans-serif;color:#303b35}.overlay,.overlay *{box-sizing:border-box}.dialog{width:min(720px,100%);min-width:0;max-width:100%;max-height:calc(100dvh - 32px);margin:auto;padding:clamp(18px,3vw,32px);overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.editor input:not([type=checkbox]),.editor select,.editor textarea{display:block;width:100%;min-width:0;max-width:100%}.editor .panel input,.editor .panel select{margin:5px 0}.editor .close{position:sticky;top:0;z-index:1;background:#fff}.editor .form-actions{position:sticky;bottom:-1px;background:#fff;padding-bottom:12px}.heading{gap:16px;flex-wrap:wrap}.cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr))}.card-main>div:last-child{min-width:0;overflow-wrap:anywhere}.shell{min-width:0}main{width:100%;min-width:0}.event-row>*{min-width:0;max-width:100%}@media(max-width:520px){.overlay{padding:8px}.dialog{max-height:calc(100dvh - 16px);padding:18px;border-radius:12px}.editor .form-actions{gap:8px}.editor .form-actions button{flex:1}.card-main{gap:12px}.card-main img,.poster{width:86px;height:128px}.event-row{padding:12px 0}.heading h1{font-size:28px}nav{gap:8px;flex-wrap:wrap}}
</style>
<style scoped>.editor .close,.editor .form-actions{position:static}.editor .close{float:none;display:block;margin-left:auto}.editor input[type=checkbox]{accent-color:#6F9DD4}</style>

<style>.modal-backdrop:has(.drama-submission-confirm){z-index:1200}.drama-submission-confirm .close-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px}.drama-submission-confirm .close-actions button{min-height:42px;padding:10px;font:inherit;border:1px solid #9aacc044;border-radius:8px;color:inherit;background:transparent}</style>

